{
  "til_number": "TIL 1584-R1",
  "revision": "R1",
  "title": "7FA TURBINE SHELL INLET BLEED HEAT (IBH) EXTRACTION PIPE WELD CRACKING",
  "publish_date": "2011-03-08",
  "reason_for_revision": "The purpose of revision is to provide recommended inspection intervals and update the affected unit list and application to include 7F, 7FA and 7FA+.",
  "purpose": "To recommend inspection of 7FA turbine shell IBH extraction port cover flange pipes for potential weld cracking, and to specify corrective action if required.",
  "compliance_category_code": "S",
  "compliance_category_text": "S - Safety",
  "recurring_indicator_if_found": null,
  "coarse_outage_type": "next shutdown",
  "scope_of_work": [
    "Dye penetrant inspection of the weld joint on 7FA turbine shell IBH extraction port cover flange pipes by a certified level II NDT inspector.",
    "If cracks are found, perform repair (grind off cracked section and repair weld per GE weld specification P8A-AG3 or equivalent) or replacement (replace flange and install new flange gasket per MLI-0705 assembly drawing), then re-inspect per the recommended schedule."
  ],
  "service_recommendation_line_items": [
    "Perform dye penetrant inspection of the pipe to cover flange weld joint by a certified level II NDT inspector: first inspection at the first Hot Gas Path inspection (HGPI); if beyond first HGPI, inspect at the next planned shutdown opportunity.",
    "Re-inspect the IBH weld joint at every HGPI/Major inspection, or at a convenient planned outage.",
    "If cracks are indicated on the pipe or on the weld: Option 1 Repair—grind off cracked section and perform repair welding using GE weld specification P8A-AG3 or equivalent; Option 2 Replacement—replace the flange with a new part and replace the flange gasket; install per MLI-0705 assembly drawing.",
    "Re-inspect repaired, replaced, and original IBH weld joint per the schedule (first HGPI / next planned shutdown if beyond first HGPI; then every HGPI/Major or convenient planned outage)."
  ],
