  "title": "7F.04 S3B CREEP DISTRESS",
  "publish_date": "2024-02-28",
  "reason_for_revision": "Add Tech Advanced Gas Path (AGP) configuration, clarify overall recommendations, and update the TIL Affected Units List.",
  "purpose": "Inform affected users of Stage 3 Bucket (S3B) and Stage 3 Shroud (S3S) modifications required for more reliable gas turbine operation. Failure to comply with these recommendations may result in a forced outage and/or increased part fallout during refurbishment.",
  "compliance_category_code": "A",
  "compliance_category_text": null,
  "recurring_indicator_if_found": null,
