{
  "til_number": "2511",
  "revision": null,
  "title": "F.05 & HA COMPRESSOR-SECTION RETENTION-KEY IMPROVEMENTS",
  "publish_date": "2024-06-06",
  "reason_for_revision": null,
  "purpose": "To inform affected users about:\n1. The potential for keys retaining sub-assemblies such as stator vane segments, inducer, high pressure packing seal, air-inducer seal, and/or casing treatment ring to overcome staked retention, which can result in object drops during casing lifts.\n2. The availability of an improved key retention method, and the recommendation to install the improved key retention modification during a planned major inspection.",
  "compliance_category_code": "S",
  "compliance_category_text": "S - Safety",
  "recurring_indicator_if_found": null,
  "coarse_outage_type": "Next Scheduled Outage",
  "scope_of_work": [
    "Machine threaded holes and counterbores on the UH compressor-section casings at the HJ to accept retention screws.",
    "Install new keys to retain stator-vanes, HPPS, AIS1, inducer2, and CT ring3; torque retention screws to specification.",
    "Stake around the keys at 4x places to serve as secondary retention."
  ],
  "service_recommendation_line_items": [
    "Apply the newly configured retention key modification at the next major inspection (MI) when all the compressor section upper-half (UH) casings will be removed.",
    "Optionally apply the modification at an earlier opportunity, if all the affected compressor section UH casings are removed prior to an MI.",
    "Prior to lifting any UH casing, take additional precautions and, if possible, inspect the retention keys for any potential abnormalities such as a displaced key; once the UH casing is separated, telescoping mirrors may be used to perform this inspection."
  ],
  "completion_criteria_text": "The TIL is considered as complete once the newly configured key retention modification is installed.",
  "maintenance_trigger_text": "Next major inspection (MI) when all the compressor section upper-half (UH) casings will be removed; may optionally be applied at an earlier opportunity if all affected UH casings are removed prior to an MI.",
  "recommended_interval_or_trigger": [
